  final run = ts.SequenceRun();

  stdHeader =
      'Sequence File' +
      fileGlobals.SEPARATOR +
      'Sequence' +
      fileGlobals.SEPARATOR +
      'Step Group' +
      fileGlobals.SEPARATOR +
      'Step Index' +
      fileGlobals.SEPARATOR +
      'Indent Level' +
      fileGlobals.SEPARATOR +
      'Step' +
      fileGlobals.SEPARATOR +
      'Icon' +
      fileGlobals.SEPARATOR +
      'Descirption' +
      fileGlobals.SEPARATOR +
      'Settings' +
      fileGlobals.SEPARATOR +
      'Requirement[0]' +
      fileGlobals.SEPARATOR; // Populate Standard Header
  // step loop (Custom): init RunState.LoopIndex = 0; while RunState.LoopIndex < FileGlobals.LargestParameterCount; increment RunState.LoopIndex += 1; status RunState.LoopNumPassed / RunState.LoopNumIterations < 1 ? "Failed" : "Passed"
  parametersHeader =
      parametersHeader +
      'Parameter[' +
      ts.str(runState.LoopIndex) +
      '] Name' +
      fileGlobals.SEPARATOR +
      'Parameter[' +
      ts.str(runState.LoopIndex) +
      '] Value' +
      fileGlobals.SEPARATOR; // Create Parameter's Header
  ts.eval(
    'Locals.ParametersHeader = Trim(Locals.ParametersHeader, FileGlobals.SEPARATOR)',
  ); // Remove the Last Separator
  seqDocString =
      stdHeader +
      parametersHeader +
      '\n' +
      seqDocString; // Add Header To Steps Doc String

  return run.status;
}

/// Sequence `Get SubSequence Parameters` — Extracts parameters of a SubSequence call and return them as a tab-separated string..
Future<String> getSubSequenceParameters({
  int numberOfParameters = 0,
  dynamic currentStep,
  String parametersList = '',
}) async {
  dynamic currentParameter = null; // Ref
  int x = 0; // Num — default: 0

  final run = ts.SequenceRun();

  // ── main ──
  for (
    x = 0;
    x < currentStep.TS.SData.ActualArgs.GetNumSubProperties('');
    x += 1
  ) {
    currentParameter = currentStep.TS.SData.ActualArgs.GetNthSubProperty(
      '',
      x,
      0,
    ); // Retrieve Parameter
    parametersList =
        parametersList +
        currentParameter.Name +
        fileGlobals.SEPARATOR +
        currentParameter.Expr +
        fileGlobals.SEPARATOR; // Parse SubSequence Parameters
  }

  // ── cleanup ──
  numberOfParameters = ++x; // Set the Number of Parameters in the Module

  return run.status;
}

/// Sequence `Get LabVIEW Module Parameters` — Extracts parameters of a LabVIEW Code Module and return them as a tab-separated string..
Future<String> getLabViewModuleParameters({
  int numberOfParameters = 0,
  dynamic currentStep,
  String parametersList = '',
}) async {
  int x = 0; // Num — default: 0
  dynamic currentParameter = null; // Ref

  final run = ts.SequenceRun();

  // ── main ──
  for (final element in ts.iterate(currentStep.TS.SData.ViCall.Parms)) {
    currentParameter = element;
    parametersList =
        parametersList +
        currentParameter.Label +
        fileGlobals.SEPARATOR +
        currentParameter.ArgVal +
        fileGlobals.SEPARATOR; // Parse Module Parameters
  }

  // ── cleanup ──
  numberOfParameters = ++x; // Set the Number of Parameters in the Module

  return run.status;
}

